package com.privatezero.stadiumpad;
import java.io.*;import java.util.*;import static com.privatezero.stadiumpad.Data.*;
/** Connects ONLY to a synthetic loopback peer; no hardware addresses accepted. */
public final class ParitySessionTests {
 public static void main(String[] args)throws Exception{Session s=new Session(new File(args[1]));s.connect("127.0.0.1",Integer.parseInt(args[0]));Thread events=new Thread(()->{try{while(!s.closed)s.event();}catch(Exception ignored){}});events.setDaemon(true);events.start();try{String kind=args[2];if(kind.equals("eq-stream")){GlobalEQ.State current=s.eq.read();current=s.eq.stage(current,0,Arrays.asList(new GlobalEQ.Change(3,3,.125)),null,null);Thread.sleep(150);current=s.eq.stage(current,0,Arrays.asList(new GlobalEQ.Change(3,3,.25)),null,null);s.eq.beginCommit(current);current=s.eq.stage(current,0,Arrays.asList(new GlobalEQ.Change(3,3,.375)),null,null);Thread.sleep(1100);s.eq.beginCommit(current);System.out.println("PASS late own EQ echo did not rewind newer state");}else if(kind.equals("eq")){GlobalEQ.State before=s.eq.read();GlobalEQ.State changed=s.eq.stage(before,0,Arrays.asList(new GlobalEQ.Change(3,3,.125)),null,null);long revision=s.eq.beginCommit(changed);long deadline=System.nanoTime()+4_000_000_000L;while(s.eq.confirm(changed,revision)==null){require(System.nanoTime()<deadline,"EQ readback not confirmed");Thread.sleep(100);}System.out.println("PASS Android EQ live/commit/readback");}else if(kind.equals("command")){Models.State before=s.snapshot();CommandCenter.Context context=new CommandCenter.Context(before,new CommandCenter.Source("stomp",1,1),0);Models.State after=CommandCenter.edit(s,context,CommandCenter.Operation.family(6));CommandCenter.Parameter p=new CommandCenter.Parameter(map("id",1,"name","Command","type","i","minimum",0,"maximum",3));CommandCenter.edit(s,new CommandCenter.Context(after,context.source,0),CommandCenter.Operation.parameter(p,1));System.out.println("PASS Android command allocation/readback");}else{Matrix.State before=s.matrix.read();s.matrix.channels(s.matrix.midi());final int[] sends={0};Matrix.Sender sender=(k,o,src,field,v,ch)->{sends[0]++;};if(kind.equals("matrix-clear"))s.matrix.clear(before,1,sender);else if(kind.equals("matrix-panel"))s.matrix.panel(1,false,sender);else s.matrix.set(before,1,14,kind.equals("matrix-pan")?1:2,kind.equals("matrix-pan")?32:127,sender);require(sends[0]>0,"Expected a bounded MIDI plan");System.out.println("PASS Android Matrix live confirmation "+sends[0]);}}finally{s.close();}}
}
